questionvariables.text:
/* Local Context */
places : ["Githunguri", "Limuru", "Kikuyu", "Ruiru", "Kiambu"];
place : rand(places);

/* Production Variables in multiples of 10 */
min_val : rand_with_step(120, 160, 10);
max_val : min_val + rand_with_step(30, 60, 10);

/* Target Answers */
ta1 : min_val;
ta2 : max_val;
ta3 : [min_val, 0];
ta4 : [max_val, 0];

feedbackvariables.text:
/* Extract the x-coordinates. Order doesn't matter since they can drag either point */
graph_min : min(ans3[1], ans4[1]);
graph_max : max(ans3[1], ans4[1]);
alg_min : min(ans1, ans2);
alg_max : max(ans1, ans2);
